$suppliers=$conn->query("SELECT id,supplier_name,balance FROM suppliers WHERE status='Active' ORDER BY supplier_name")->fetchAll();
$recent=$conn->query("SELECT sp.*,s.supplier_name,u.full_name FROM supplier_payments sp JOIN suppliers s ON s.id=sp.supplier_id JOIN users u ON u.id=sp.user_id ORDER BY sp.id DESC LIMIT 30")->fetchAll();
