require_once __DIR__.'/../../includes/header.php';require_once __DIR__.'/../../includes/sidebar.php';?>
<main class="content"><h1>Supplier Payments</h1><p>Settle supplier payables and maintain the supplier ledger.</p><?php if($flash):?><div class="flash"><?=e($flash)?></div><?php endif;?><div class="grid"><div class="panel"><h3>Make Payment</h3><form method="post" action="store.php"><input type="hidden" name="csrf_token" value="<?=e(csrf_token())?>"><label>Supplier<select name="supplier_id" required><option value="">Select supplier</option><?php foreach($suppliers as $s):?><option value="<?=$s['id']?>"><?=e($s['supplier_name'])?> — KES <?=number_format((float)$s['balance'],2)?></option><?php endforeach;?></select></label><label>Amount<input type="number" name="amount" min=".01" step=".01" required></label><label>Payment Method<select name="payment_method" id="sp_method"><option>Cash</option><option>M-Pesa</option><option>Bank</option><option>Cheque</option><option>Other</option></select></label><label id="sp_phone" style="display:none">M-PESA Phone<input name="mpesa_phone" placeholder="07XXXXXXXX"></label><label>Reference<input name="transaction_reference"></label><label>Notes<input name="notes"></label><button class="btn">Record Supplier Payment</button></form></div><div class="panel"><h3>Payment History</h3><div class="scroll"><table><thead><tr><th>Receipt</th><th>Date</th><th>Supplier</th><th>Amount</th><th>Method</th><th>Reference</th></tr></thead><tbody><?php foreach($recent as $p):?><tr><td><?=e($p['receipt_number'])?></td><td><?=e($p['payment_date'])?></td><td><?=e($p['supplier_name'])?></td><td>KES <?=number_format((float)$p['amount'],2)?></td><td><?=e($p['payment_method'])?></td><td><?=e($p['transaction_reference']??'')?></td></tr><?php endforeach;?></tbody></table></div></div></div><script>document.getElementById('sp_method').addEventListener('change',function(){document.getElementById('sp_phone').style.display=this.value==='M-Pesa'?'block':'none';});</script></main><style>.grid{display:grid;grid-template-columns:360px 1fr;gap:18px}.panel{background:#fff;padding:20px;border-radius:12px;box-shadow:0 1px 5px #0001}.panel label{display:block;font-size:12px;font-weight:700;margin:12px 0}.panel input,.panel select{display:block;width:100%;box-sizing:border-box;padding:10px;margin-top:5px;border:1px solid #dbe3ec;border-radius:7px}.btn{padding:11px 15px;border:0;border-radius:7px;background:#004a99;color:#fff;font-weight:700;width:100%}.flash{padding:12px;background:#ecfdf5;color:#166534;border-radius:8px;margin-bottom:15px}.scroll{overflow:auto}table{width:100%;border-collapse:collapse}th,td{padding:10px;border-bottom:1px solid #e5e7eb;text-align:left;font-size:13px}th{background:#004a99;color:#fff}@media(max-width:900px){.grid{grid-template-columns:1fr}}</style><?php require_once __DIR__.'/../../includes/footer.php';?>